css:
[data-bz-node="dr-card"] { border-radius: var(--radius-modal); box-shadow: 0 30px 80px -40px color-mix(in srgb, var(--ink) 30%, transparent); }
[data-bz-node^="dr-check"] { padding-block: 6px !important; }
[data-bz-node^="dr-check"] p { position: relative; padding-left: 34px; font-weight: 600 !important; color: var(--ink) !important; font-size: 15.5px; }
[data-bz-node^="dr-check"] p::before { content: '✓'; position: absolute; left: 0; top: 1px; width: 22px; height: 22px; border-radius: 50%; background: var(--accent); color: #fff; display: grid; place-items: center; font: 800 12px/1 var(--font-body); }
[data-bz-node="dr-body"] + [data-bz-node^="dr-check"] { margin-top: var(--space-3); }
[data-bz-node="dr-note"] p { font-size: 13px !important; color: var(--muted) !important; text-align: center; }
@media (max-width: 640px) { [data-bz-node="dr-card"] { padding: var(--space-5) !important; } }
/* The design shows placeholders only; the labels stay for screen readers. */
[data-bz-node="dr-form"] .bz-label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
[data-bz-node="dr-card"] > .bz-block, [data-bz-node="dr-card"] .bz-row { position: relative; }
